// Run after updating the canonical screenshots in public/assets/app.
// Generated files are committed so normal deployments need no image encoding.
import { createHash } from "node:crypto";
import { mkdir, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const output = join(root, "public", "_media");
const widths = [320, 480, 600, 720];
const names = ["home-light", "home-dark", "thread", "inbox", "display", "explore", "compose", "profile", "onboarding-globe-dark", "login-locked-dark"];
const generated = new Set();

await mkdir(output, { recursive: true });

async function asset(name, format, buffer) {
  const hash = createHash("sha256").update(buffer).digest("hex").slice(0, 12);
  const filename = `${name}-${hash}.${format}`;
  generated.add(filename);
  await writeFile(join(output, filename), buffer);
  return `/_media/${filename}`;
}

const screenshots = {};
let oldBytes = 0;
let newBytes = 0;
for (const name of names) {
  const source = join(root, "public", "assets", "app", `${name}.webp`);
  const formats = { avif: [], webp: [] };
  for (const width of widths) {
    // Preserve the existing WebP pixels where a matching fallback exists.
    const webp = width === 320
      ? await sharp(source).resize({ width }).webp({ quality: 82, effort: 6 }).toBuffer()
      : await readFile(width === 720 ? source : source.replace(/\.webp$/, `-${width}.webp`));
    const avif = await sharp(source).resize({ width }).avif({ quality: 60, effort: 6, chromaSubsampling: "4:4:4" }).toBuffer();
    formats.webp.push(`${await asset(`${name}-${width}`, "webp", webp)} ${width}w`);
    formats.avif.push(`${await asset(`${name}-${width}`, "avif", avif)} ${width}w`);
    if (width === 720) {
      oldBytes += webp.length;
      newBytes += avif.length;
    }
  }
  screenshots[name] = {
    src: formats.webp.at(-1).split(" ")[0],
    webp: formats.webp.join(", "),
    avif: formats.avif.join(", "),
  };
}

const images = {};
for (const [name, filename, options] of [
  ["brand", "moro-icon-64.png", { quality: 90, effort: 6 }],
  ["icon", "moro-icon-192.png", { quality: 90, effort: 6 }],
  ["storeBadge", "download-on-app-store.png", { lossless: true, effort: 6 }],
  ["qrCode", "app-qrcode-tight.png", { lossless: true, effort: 6 }],
]) {
  const buffer = await sharp(join(root, "public", "assets", filename)).webp(options).toBuffer();
  images[name] = await asset(name, "webp", buffer);
}

await writeFile(join(root, "src", "home", "images.generated.js"),
  `// Generated by pnpm images:optimize. Do not edit by hand.\nexport const screenshots = ${JSON.stringify(screenshots, null, 2)};\n\nexport const images = ${JSON.stringify(images, null, 2)};\n`);

// Only this script owns _media; discard obsolete generated variants.
for (const filename of await readdir(output)) {
  if (!generated.has(filename)) await rm(join(output, filename));
}
console.log(`Generated ${generated.size} versioned images. Full-size screenshots: ${(oldBytes / 1024).toFixed(1)} → ${(newBytes / 1024).toFixed(1)} KiB (${Math.round((1 - newBytes / oldBytes) * 100)}% smaller).`);
